from django.utils.text import slugify


def isi_slug_paket(apps, schema_editor):
    """Paket lama (tanpa slug) diberi slug dari namanya, supaya kolom bisa dijadikan unik."""
    Package = apps.get_model('app', 'Package')
    dipakai = set()
    for p in Package.objects.all().order_by('pk'):
        dasar = slugify(p.name) or f'paket-{p.pk}'
        slug, n = dasar, 2
        while slug in dipakai:
            slug = f'{dasar}-{n}'
            n += 1
        dipakai.add(slug)
        p.slug = slug
        p.save(update_fields=['slug'])


